        'anatomy_conditions' => '<strong>शर्तें</strong> <em>(वैकल्पिक)</em> &mdash; ऐसे फ़िल्टर जो तय करते हैं कि वर्कफ़्लो चलेगा या नहीं। सभी शर्तों का मिलान होना ज़रूरी है (AND अर्थ)। <em>"केवल तब जब priority Critical हो AND department Finance हो।"</em>',
        'anatomy_actions' => '<strong>क्रियाएँ</strong> <em>(एक या अधिक)</em> &mdash; ट्रिगर सक्रिय होने और शर्तें पूरी होने पर करने वाली चीज़ें। ऊपर से नीचे, क्रम में चलती हैं।',
