        'actions_row3_args' => 'ticket_id, priority_id',
        'actions_row4_does' => 'किसी टिकट का owner / assignee सेट करता है। <code>assigned_analyst_id</code> और <code>owner_id</code> दोनों को अपडेट करता है ताकि दाईं ओर के पैनल का Owner फ़ील्ड सिंक में बना रहे।',
        'actions_row4_args' => 'ticket_id, analyst_id',
        'actions_row5_does' => 'टिकट के ऑडिट ट्रेल में एक फ़्री-टेक्स्ट नोट जोड़ता है। आंतरिक &mdash; कभी भी requester को नहीं भेजा जाता।',
        'actions_row5_args' => 'ticket_id, note',
        'actions_row6_does' => 'टिकट के mailbox का उपयोग करके requester को (या किसी भी पते पर) एक ईमेल भेजता है। Subject के आगे <code>[SDREF:&hellip;]</code> जोड़ा जाता है ताकि जवाब अपने आप उसी थ्रेड में जुड़ें। <strong>अब टिकट वैकल्पिक है</strong> &mdash; इसके बजाय भेजने के लिए एक mailbox चुनें, जो यह बताता है कि कोई फ़ॉर्म किसी टिकट के बनने से पहले ही सबमिशन की पावती कैसे देता है। बिना टिकट के जवाब को थ्रेड करने के लिए कुछ नहीं होता, इसलिए ऐसे जवाब को न्योता देने के बजाय जो कहीं नहीं पहुँचता, &ldquo;reply above this line&rdquo; मार्कर हटा दिया जाता है।',
        'actions_row6_args' => 'ticket_id, to, subject, body',
        'actions_row7_does' => 'एक टास्क बनाता है। अगर <code>ticket_id</code> दिया गया हो तो अपने आप स्रोत टिकट से लिंक हो जाता है। खाली छोड़ने पर स्थिति / प्राथमिकता वर्कस्पेस की डिफ़ॉल्ट सेटिंग लेती हैं।',
        'actions_row7_args' => 'title, description, status_id, priority_id, assignee_id, ticket_id',
        'actions_row8_does' => 'एक नया टिकट बनाता है। <em>"new-starter form &rarr; IT + HR + Facilities tickets"</em> जैसे फ़ैन-आउट वर्कफ़्लो के लिए उपयोगी। जब घटना एक <strong>फ़ॉर्म सबमिशन</strong> लेकर आती है, तो टिकट अपने आप सही तरीके से बनता है &mdash; requester उसके असली अकाउंट से मिलाया जाता है, company वहीं से ली जाती है, और अगर body खाली छोड़ दें तो सबमिट किए गए जवाब एक टेबल के रूप में दिखते हैं। यहाँ आप जो भी सेट करें वह हमेशा प्राथमिकता में रहता है; फ़ॉर्म केवल वही भरता है जो आपने खाली छोड़ा था।',
        'actions_row8_args' => 'subject, body, priority_id, department_id, type_id, assigned_analyst_id, from_email, from_name',
        'actions_row9_does' => 'किसी बाहरी URL पर एक संदेश POST करता है &mdash; Slack, Teams, Discord, PagerDuty, Zapier/Make या इनकमिंग वेबहुक स्वीकार करने वाले किसी भी सिस्टम में घटनाएँ भेजें। कोई चैट प्रीसेट चुनें, Full record भेजें (पूरा ऑब्जेक्ट JSON के रूप में, ठीक REST API जैसा), या अपना खुद का कस्टम JSON बॉडी टेम्पलेट बनाएँ। एक वैकल्पिक HMAC सिग्निंग सीक्रेट का समर्थन करता है, और एक Send test बटन जो सहेजने से पहले एंडपॉइंट का असली रिस्पॉन्स दिखाता है।',
        'actions_row9_args' => 'preset, url, message (presets), body (custom JSON), secret (वैकल्पिक)',
        'actions_note' => 'हर क्रिया के आवश्यक आर्ग्युमेंट फ़ॉर्म में <code>*</code> से चिह्नित होते हैं। आवश्यक आर्ग्युमेंट गायब होने पर क्रिया निष्पादन के समय विफल हो जाती है &mdash; इंजन उस विफलता को निष्पादन पंक्ति में लॉग करता है और बाकी चेन रोक देता है।',
        'actions_webhook_callout' => '<strong><code>send_webhook</code> क्रिया अपने आप में एक बड़ा विषय है</strong> &mdash; चैट प्रीसेट, पूरे ऑब्जेक्ट वाले &ldquo;Full record&rdquo; पेलोड, HMAC सिग्निंग, एक Send-test बटन, रीट्राई के साथ बैकग्राउंड डिलीवरी, और एक हेल्थ डैशबोर्ड। इसकी अपनी समर्पित मार्गदर्शिका है: <a href="help-webhooks.php"><strong>वेबहुक मार्गदर्शिका &rarr;</strong></a>',
        'variables_heading' => 'वेरिएबल &mdash; <code>{{path.to.field}}</code>',
        'variables_intro' => 'कोई भी फ़्री-टेक्स्ट क्रिया आर्ग्युमेंट उस घटना से मान खींच सकता है जिसने उसे ट्रिगर किया। कोड हाथ से टाइप करने की ज़रूरत नहीं: हर वेरिएबल-फ़्रेंडली फ़ील्ड में एक <strong>Edit with variables</strong> बटन होता है जो एक बड़ा एडिटर खोलता है जिसके साथ <strong>बगल में वेरिएबल की खोज-योग्य सूची</strong> होती है — एक पर क्लिक करें और वह आपके कर्सर पर आ जाता है। एक लाइव पूर्वावलोकन तैयार टेक्स्ट दिखाता है जिसमें हर कोड की जगह वह मान आ जाता है जिसके लिए वह खड़ा है।',
        'variables_scoped' => '<strong>आपको हमेशा केवल वे वेरिएबल दिए जाते हैं जिन्हें ट्रिगर वास्तव में भर सकता है।</strong> यह सुनने में लगने से ज़्यादा मायने रखता है: कोई गायब वेरिएबल त्रुटि नहीं देता, वह चुपचाप एक <em>खाली स्ट्रिंग</em> में बदल जाता है। इसलिए <code>knowledge.published</code> पर बना कोई वर्कफ़्लो जिसके संदेश में <code>{{ticket.subject}}</code> लिखा हो, विफल नहीं होगा — वह बस वहाँ खाली जगह पोस्ट करेगा जहाँ subject होना चाहिए था, और आपको कभी पता नहीं चलेगा। knowledge घटना में कोई टिकट नहीं होता, इसलिए पिकर टिकट वेरिएबल दिखाता ही नहीं, और अगर आप फिर भी एक टाइप करें तो फ़ील्ड आपको चेतावनी देता है कि यह खाली आएगा।',
        'variables_names' => '<strong>id नहीं, नाम इस्तेमाल करें।</strong> <code>{{ticket.priority_id}}</code> <code>4</code> के रूप में दिखता है &mdash; एक संख्या जिसे आपका Slack चैनल पढ़ने वाला कोई भी व्यक्ति समझ नहीं सकता। इसलिए हर लुकअप फ़ील्ड का एक पढ़ने-योग्य जुड़वाँ होता है: <code>{{ticket.priority_name}}</code> <strong>Critical</strong> दिखाता है। पिकर नाम को सादे विकल्प के रूप में सूचीबद्ध करता है (<em>Ticket &middot; Priority</em>) और संख्यात्मक वाले को <em>(id)</em> से चिह्नित करता है, क्योंकि जो संदेश कोई व्यक्ति पढ़ेगा उसमें लगभग हमेशा नाम ही चाहिए होता है। id फिर भी वहीं मौजूद हैं जब आपको उनकी ज़रूरत हो &mdash; किसी शर्त के लिए, या किसी ऐसे प्राप्तकर्ता सिस्टम के लिए जो उन्हीं की अपेक्षा करता है। change ट्रिगर पर आपको <code>{{old_priority_name}}</code> / <code>{{new_priority_name}}</code> भी मिलते हैं, ताकि "escalated from High to Critical" अपने आप लिखा जाए।',
        'variables_number' => '<strong>row id नहीं, संदर्भ बताएँ।</strong> <code>{{ticket.id}}</code> आंतरिक डेटाबेस id है (<code>83</code>) &mdash; requester के लिए बेमानी। <code>{{ticket.number}}</code> वह संदर्भ है जो वे आपको वास्तव में वापस बताते हैं (<code>ETC-623-64409</code>), और यही ईमेल subject या चैट अलर्ट में होना चाहिए। <code>{{problem.number}}</code> के लिए भी यही बात है। <strong>एक अपवाद:</strong> <em>Ticket ID</em> क्रिया आर्ग्युमेंट को <code>{{ticket.id}}</code> ही रहना चाहिए &mdash; वह फ़ील्ड इंजन को बताती है <em>किस रिकॉर्ड पर काम करना है</em>, और वह इसे row id से खोजता है। जो शब्द कोई व्यक्ति पढ़े उनमें number इस्तेमाल करें; id को अंदरूनी काम में ही रहने दें।',
        'variables_full' => 'जहाँ कोई ट्रिगर पूरा रिकॉर्ड लेकर आता है, वहाँ आपको <code>{{&lt;object&gt;.full}}</code> भी मिलता है &mdash; जैसे <code>{{ticket.full}}</code> &mdash; जो पूरे रिकॉर्ड को JSON के रूप में, ठीक उसी रूप में एम्बेड करता है जैसे REST API उसे लौटाता है। और <code>{{event}}</code> हमेशा उस ट्रिगर के नाम में बदल जाता है जो सक्रिय हुआ।',
        'variables_common' => 'टिकट ट्रिगर के लिए सामान्य वेरिएबल:',
        'variables_li1' => '<code>{{ticket.id}}</code>, <code>{{ticket.subject}}</code>, <code>{{ticket.priority_id}}</code>, <code>{{ticket.status_id}}</code>',
        'variables_li2' => '<code>{{ticket.department_id}}</code>, <code>{{ticket.type_id}}</code>, <code>{{ticket.assigned_analyst_id}}</code>',
        'variables_li3' => '<code>{{ticket.owner_id}}</code>, <code>{{ticket.created_by}}</code>, <code>{{ticket.requester_email}}</code>',
        'variables_li4' => '<code>ticket.status_changed</code> / <code>ticket.priority_changed</code> के लिए: साथ ही <code>{{old_status_id}}</code>, <code>{{new_status_id}}</code>, <code>{{old_priority_id}}</code>, <code>{{new_priority_id}}</code>',
        'variables_li5' => '<code>ticket.assigned</code> के लिए: साथ ही <code>{{analyst_id}}</code>, <code>{{team_id}}</code>',
        'variables_tip' => '<strong>सर्वोत्तम तरीका:</strong> क्रिया के <code>ticket_id</code> फ़ील्ड में, कोई खास id टाइप करने के बजाय डिफ़ॉल्ट <code>{{ticket.id}}</code> ही रहने दें &mdash; इस तरह वर्कफ़्लो उसी टिकट पर काम करता है जिसने उसे ट्रिगर किया, किसी तय टिकट पर नहीं।',
        'variables_chain_heading' => 'पहले की किसी क्रिया ने जो बनाया उसका उपयोग करना',
        'variables_chain_intro' => 'क्रियाएँ क्रम में चलती हैं, और बाद की कोई क्रिया पहले की क्रिया ने जो किया उसका संदर्भ ले सकती है। यही वजह है कि <em>&ldquo;एक टिकट बनाओ, फिर उस व्यक्ति को उसका टिकट नंबर ईमेल करो&rdquo;</em> एक असंभव काम नहीं बल्कि एक ही वर्कफ़्लो बन जाता है।',
        'variables_chain_last' => '<code>{{last.ticket_id}}</code> &mdash; जो भी ठीक इससे पहले वाली क्रिया ने बनाया।',
        'variables_chain_steps' => '<code>{{steps.1.ticket_number}}</code> &mdash; कैनवास पर उसके बगल में दिखाई गई संख्या से पहचानी गई एक खास क्रिया। इसका उपयोग तब करें जब आपको चाहिए वाली क्रिया ठीक पहले वाली न हो।',
        'variables_chain_note' => 'ये जानबूझकर अपने ही नामों के अंतर्गत रहते हैं, वर्कफ़्लो के अपने डेटा को अधिलेखित करने के बजाय। अगर टिकट बनाने से <code>{{ticket.id}}</code> बदल जाता, तो किसी टिकट वर्कफ़्लो का हर बाद का चरण चुपचाप नए टिकट की ओर इशारा करने लगता, न कि उस टिकट की ओर जिसने वर्कफ़्लो शुरू किया था।',
        'actions_forms_callout' => '<strong>फ़ॉर्म भी ये क्रियाएँ चला सकते हैं।</strong> वर्कफ़्लो बनाने के बजाय, कोई फ़ॉर्म खोलें और उसके <strong>What happens next</strong> टैब का उपयोग करके बताएँ कि सबमिट, स्वीकृत या अस्वीकृत होने पर क्या होना चाहिए। यह वही इंजन और वही क्रियाएँ हैं, और रन उसी निष्पादन लॉग में दिखते हैं &mdash; फ़ॉर्म एडिटर बस उसी एक फ़ॉर्म तक सीमित एक दूसरा रास्ता है। यहाँ वर्कफ़्लो तभी बनाएँ जब कोई नियम कई फ़ॉर्म तक फैला हो।',
        'ai_heading' => 'AI सह-लेखक',
        'ai_intro' => 'टूलबार पर <strong>AI co-author</strong> पर क्लिक करें और वर्कफ़्लो को सादे शब्दों में बताएँ। AI एक संरचित प्रस्ताव लौटाता है &mdash; trigger, conditions, actions &mdash; जिसे आप कैनवास पर <em>Apply</em> कर सकते हैं या <em>Discard</em> कर सकते हैं।',
        'ai_examples' => 'अच्छे से काम करने वाले उदाहरण:',
        'ai_ex1' => '<em>"जब कोई Critical-priority टिकट बनाया जाए, तो एक नोट जोड़ो जिसमें लिखा हो \'P1 &mdash; कृपया 15 मिनट के भीतर जवाब दें\'।"</em>',
        'ai_ex2' => '<em>"जब <code>finance@acme.com</code> से कोई टिकट बनाया जाए, तो उसे मुझे असाइन करो और priority को High सेट करो।"</em>',
        'ai_ex3' => '<em>"जब कोई टिकट बंद हो, तो requester को धन्यवाद देते हुए और फ़ीडबैक माँगते हुए एक ईमेल भेजो।"</em>',
        'ai_catalogue' => 'AI इंजन का पूरा कैटलॉग जानता है &mdash; हर ट्रिगर, शर्त ऑपरेटर, क्रिया, और उपलब्ध लुकअप-टेबल मान &mdash; इसलिए यह केवल वही सुझा सकता है जो वाकई काम करेगा। अगर आप किसी मौजूदा वर्कफ़्लो पर पुनरावृत्ति करते हैं (<em>"now only match Finance"</em> / <em>"add an action to log the ticket id"</em>) तो यह नए सिरे से शुरू करने के बजाय कैनवास पर जो पहले से है उसे संपादित करता है।',
        'ai_config' => 'प्रदाता (Anthropic / OpenAI), मॉडल और API key को <strong>Workflow &rarr; Settings &rarr; AI</strong> के अंतर्गत कॉन्फ़िगर करें। कुंजियाँ प्रति मॉड्यूल संग्रहीत होती हैं ताकि बिलिंग और एक्सेस बारीक रह सकें।',
        'templates_heading' => 'टेम्पलेट से शुरू करें',
        'templates_intro' => 'Workflows सूची पर <strong>New from template</strong> बटन उन कामों के लिए तैयार रेसिपी की एक गैलरी खोलता है जिन्हें ज़्यादातर सर्विस डेस्क सबसे पहले स्वचालित करते हैं &mdash; नए टिकट की अपने आप पावती देना, P1 पर टीम को अलर्ट करना, new-starter फ़ॉर्म को IT, HR और Facilities टिकटों में फैलाना, कोई change स्वीकृत होने पर एक implementation टास्क बनाना। इनमें से चार <strong>समय-आधारित</strong> हैं: किसी टिकट का SLA टूटने <em>से पहले</em> उसे एस्केलेट करना, टूट जाने पर अलर्ट करना, और यह याद दिलाना कि कोई कॉन्ट्रैक्ट या एसेट वारंटी जल्द ही खत्म होने वाली है। एक चुनें और यह आपके वर्कफ़्लो में एक सामान्य, पूरी तरह संपादन-योग्य वर्कफ़्लो के रूप में कॉपी हो जाता है। इसके बाद इसमें कुछ भी खास नहीं है: इसे नाम बदलना, फिर से जोड़ना या हटाना आपके हाथ में है। गैलरी <strong>category</strong> और <strong>search</strong> से फ़िल्टर होती है &mdash; जो विवरण, ट्रिगर और क्रियाओं तक भी पहुँचती है, इसलिए <em>expiry</em>, <em>slack</em> या <em>wipe</em> टाइप करने पर वह रेसिपी मिल जाती है भले ही नाम में वह शब्द न हो।',
        'templates_lookups' => 'हर इंस्टॉल अपनी statuses और priorities के अपने नाम रखता है, इसलिए कोई टेम्पलेट उन्हें सीधे हार्डकोड नहीं कर सकता। इसके बजाय यह कहता है <em>"यह इंस्टॉल Closed को जो भी कहता है"</em> और कॉपी होते समय हम असली मान ढूँढ लेते हैं। जो कुछ हम मेल नहीं कर पाते &mdash; कोई priority जो आपके पास नहीं है, या कोई मान जो केवल आप जानते हैं, जैसे कोई Slack वेबहुक URL &mdash; उसे खाली छोड़ दिया जाता है और एडिटर के ऊपर एक बैनर में सूचीबद्ध किया जाता है, ताकि आप ठीक-ठीक देख सकें कि अभी भी आपकी ज़रूरत कहाँ है।',
        'templates_scheduled' => 'चारों समय-आधारित रेसिपी को चलने के लिए एक <strong>scheduled task</strong> चाहिए, क्योंकि ये जिसका इंतज़ार करती हैं वह कोई घटना नहीं है &mdash; जब कोई SLA चुपचाप समय से बाहर हो जाता है तो कोई कुछ सेव नहीं करता, इसलिए किसी job को खुद जाकर देखना पड़ता है। अगर cron शेड्यूल नहीं किए गए हैं तो ये वर्कफ़्लो वहीं पड़े रहते हैं, सक्रिय, और कभी नहीं चलते। दोनों expiry रिमाइंडर <strong>90, 30, 7 और 1 दिन</strong> पहले भी चलते हैं, और हर रेसिपी 30-दिन वाले पर फ़िल्टर होती है &mdash; हर विंडो पर बताए जाने के लिए वह शर्त बदलें, या हटा दें। देखें <a href="#triggers">Triggers</a>।',
        'templates_callout' => 'कॉपी किया गया टेम्पलेट हमेशा <strong>बंद अवस्था में</strong> आता है। जब तक आप इसे पढ़ न लें, खाली जगह न भर लें और <em>Active</em> टिक न कर लें, तब तक इसमें मौजूद कुछ भी नहीं चलेगा &mdash; और आप पहले <strong>Dry run</strong> करके ठीक-ठीक देख सकते हैं कि यह क्या करेगा।',
        'testing_heading' => 'सहेजना और परीक्षण करना',
        'testing_save' => 'टूलबार में स्थिति संकेतक <em>Unsaved</em> / <em>Saving&hellip;</em> / <em>Saved</em> दिखाता है। सहेजने के लिए <strong>Save</strong> पर क्लिक करें। आप शून्य क्रियाओं वाले अधूरे ड्राफ़्ट भी सहेज सकते हैं &mdash; आपको रोका नहीं जाएगा, बल्कि "इस वर्कफ़्लो में अभी तक कोई क्रिया नहीं है" जैसी एक हल्की चेतावनी मिलेगी।',
        'testing_dry_heading' => 'ड्राई रन &mdash; बिना किए देखें कि यह क्या करेगा',
        'testing_dry_body' => '<strong>Dry run</strong> शर्तों का वास्तव में मूल्यांकन करता है, फिर हर क्रिया को अंजाम देने के बजाय उसका <em>वर्णन</em> करता है। यह रन <em>Recent runs</em> में <em>Dry run</em> के रूप में चिह्नित दिखाई देता है, जिसमें हर वह क्रिया सूचीबद्ध होती है जो यह करता, और <code>{{variables}}</code> पहले से भरे हुए होते हैं &mdash; ताकि आप असली ईमेल subject, असली चैट संदेश, असली नोट पढ़ सकें।',
        'testing_dry_safe' => 'कुछ भी लिखा, ईमेल किया, कतारबद्ध या भेजा नहीं जाता: न कोई टिकट बदलाव, न कोई नोट, न कोई वेबहुक डिलीवरी, और वर्कफ़्लो का run काउंटर भी अछूता रहता है। यही इसे किसी लाइव वर्कफ़्लो पर आज़माने के लिए सुरक्षित बनाता है &mdash; और यही किसी ताज़ा कॉपी किए टेम्पलेट के साथ करने वाला पहला समझदारी भरा काम है। (कोई भी signing secret आउटपुट में वापस नहीं दिखाया जाता, बल्कि छिपा दिया जाता है।)',
        'testing_log_heading' => 'निष्पादन लॉग &mdash; वास्तव में क्या हुआ',
        'testing_log_body' => 'हर वर्कफ़्लो का हर रन <strong>Execution log</strong> (Workflows हेडर में) में पहुँचता है। वर्कफ़्लो, स्थिति, ट्रिगर, तारीख या फ़्री टेक्स्ट से फ़िल्टर करें, और किसी भी रन को खोलकर <strong>चरण-दर-चरण</strong> देखें कि इंजन ने क्या किया &mdash; कौन-सी शर्त मेल खाई और कौन-सी नहीं (जिस <em>वास्तविक मान</em> से तुलना की गई उसके साथ), हर क्रिया ने क्या लौटाया या कैसे विफल हुई, और <strong>ट्रिगर पेलोड स्नैपशॉट</strong>: ठीक वही जिस पर शर्तों का परीक्षण हुआ और जहाँ से <code>{{variables}}</code> हल हुए, रन के समय कैप्चर किया गया।',
        'testing_log_why' => 'यह सुनने में लगने से ज़्यादा मायने रखता है। इंजन <strong>जानबूझकर अपनी त्रुटियाँ दबा देता है</strong> &mdash; किसी टूटे हुए वर्कफ़्लो को कभी भी उस टिकट सेव को नहीं बिगाड़ना चाहिए जिसने उसे ट्रिगर किया। यह सही फ़ैसला है, और इसका मतलब है कि एक विफल वर्कफ़्लो अन्यथा <em>पूरी तरह चुप</em> रहता है। कुछ भी आपको नहीं बताता। निष्पादन लॉग, और <strong>Watchtower पर Workflows कार्ड</strong> (जो पिछले 24 घंटों की विफलताएँ, loop-protection द्वारा रोके गए रन, और रीट्राई करते-करते हार मान चुके वेबहुक सामने लाता है), वही हैं जो इस चुप्पी को तोड़ते हैं।',
        'testing_fire_heading' => 'Test fire &mdash; वाकई इसे चलाना',
        'testing_fire' => '<strong>Test fire</strong> वर्कफ़्लो को उसकी अपनी शर्तों से बनाए गए एक कृत्रिम पेलोड के साथ वाकई में चलाता है, ताकि क्रिया वाला रास्ता वास्तव में निष्पादित हो &mdash; यह सच में वह ईमेल भेज देगा। परिणाम <em>Recent runs</em> में स्थिति (<em>success / failed / skipped</em>) और पूरे चरण-लॉग के साथ पहुँचता है।',
        'testing_real' => 'वास्तविक डेटा पर परीक्षण करने के लिए, बस वह काम करें जो इसे ट्रिगर करता है &mdash; कोई टिकट असाइन करें, उसकी प्राथमिकता बदलें, आदि। होस्ट मॉड्यूल (Tickets) से भेजा जाना लाइव है; निष्पादन लॉग हर बार सक्रिय होने को दिखाता है।',
        'triggers_heading' => 'ट्रिगर कैटलॉग',
        'triggers_intro' => 'यह कैटलॉग अब <strong>हर मॉड्यूल तक फैला हुआ है &mdash; 138 ट्रिगर और बढ़ते जा रहे हैं</strong>, सभी जुड़े हुए और लाइव। ये दो तरह के होते हैं:',
        'triggers_time_heading' => 'समय-आधारित ट्रिगर &mdash; और इन्हें जिस cron की ज़रूरत है',
        'triggers_time_body' => 'ज़्यादातर ट्रिगर एक <strong>write path</strong> से सक्रिय होते हैं: किसी ने टिकट सेव किया, तो सक्रिय होने का एक पल मिलता है। चार ऐसे नहीं हैं। <code>sla.warning</code>, <code>sla.breached</code>, <code>contract.expiring</code> और <code>asset.warranty_expiring</code> बिलकुल भी घटनाएँ नहीं हैं &mdash; <em>कुछ हुआ नहीं, बस समय बीता</em> &mdash; इसलिए एक शेड्यूल्ड job को इन्हें खुद ढूँढना पड़ता है।',
        'triggers_time_cron' => '<strong>अगर वे cron शेड्यूल नहीं हैं, तो ये ट्रिगर कभी सक्रिय नहीं होंगे।</strong> वर्कफ़्लो वहीं पड़ा रहेगा, सक्रिय, कुछ भी किए बिना। SLA घटनाएँ SLA breach-check cron से आती हैं (हर 5 मिनट में); expiry घटनाएँ <code>cron/workflow_scheduled.php</code> से (हर घंटे काफ़ी है)। सेटअप: <code>docs/workflow-scheduled-cron-setup.md</code>, या <a href="https://github.com/edmozley/freeitsm/wiki/Time-Based-Triggers" target="_blank" rel="noopener noreferrer">wiki पर Time-Based Triggers</a>, जो यह भी बताता है कि एक अब भी सच शर्त (टूटा हुआ SLA टूटा ही रहता है) हर कुछ मिनट में दोबारा क्यों नहीं चलती।',
        'triggers_time_once' => 'एक समय-आधारित शर्त <strong>सच बनी रहती है</strong> &mdash; टूटा हुआ SLA पाँच मिनट बाद भी टूटा हुआ ही रहता है &mdash; इसलिए FreeITSM एक लेजर रखता है और हर स्थिति <strong>ठीक एक बार</strong> सक्रिय होती है। जब इसके नीचे की चीज़ बदलती है तो यह फिर से तैयार हो जाता है: किसी टिकट की प्राथमिकता बढ़ाएँ और उसका SLA लक्ष्य छोटा हो जाता है, तो नई, ज़्यादा सख्त डेडलाइन को फिर से एस्केलेट होने दिया जाता है। कोई कॉन्ट्रैक्ट रिन्यू करें और अगले साल के रिमाइंडर फिर भी चलते हैं। Expiry <strong>90, 30, 7 और 1 दिन</strong> पहले चलती हैं, हर एक अपने साथ <code>window_days</code> लेकर &mdash; इसलिए "मुझे केवल 30 दिन पर याद दिलाओ" बस एक शर्त है।',
        'triggers_family_domain' => '<strong>समृद्ध डोमेन घटनाएँ</strong> &mdash; एक पूरे टाइप्ड पेलोड के साथ अर्थपूर्ण लाइफ़साइकल पल: <code>ticket.created</code>, <code>ticket.status_changed</code>, <code>change.approved</code>, <code>problem.status_changed</code>, <code>task.completed</code>, <code>service_status.incident_resolved</code>, <code>software.application_discovered</code>, और भी कई।',
        'triggers_family_forms' => '<strong>फ़ॉर्म और कैटलॉग रिक्वेस्ट</strong> &mdash; एक साधारण फ़ॉर्म के लिए <code>form.submitted</code> सक्रिय होता है। जिस फ़ॉर्म को स्वीकृति चाहिए वह इसके बजाय <code>catalogue_request.submitted</code> सक्रिय करता है, फिर आपके अप्रूवर के फ़ैसला करते ही <code>catalogue_request.approved</code> या <code>catalogue_request.rejected</code>। यह अलग घटना जानबूझकर है: इसका मतलब है कि सबमिशन पर टिकट बनाने वाला कोई नियम आपकी माँगी हुई स्वीकृति को नहीं लाँघ सकता। चारों में सबमिट किए गए जवाब होते हैं, इसलिए <code>{{submission.fields.Device type}}</code> हर चरण पर काम करता है, और चारों को एक ही फ़ॉर्म तक सीमित किया जा सकता है।',
        'triggers_family_crud' => '<strong>Create / update / delete घटनाएँ</strong> &mdash; हर पुन: उपयोग-योग्य रिकॉर्ड और सेटिंग्स लुकअप <code>&lt;entity&gt;.created</code> / <code>.updated</code> / <code>.deleted</code> भेजता है: tickets, assets, changes, problems, tasks, CMDB, contracts &amp; suppliers, calendar, software licences, network diagrams, और इनकी सभी सेटिंग्स सूचियाँ (statuses, priorities, types, tags&hellip;)।',
        'triggers_picker' => 'चूँकि सूची दर्जनों गहरी है, एडिटर का <strong>ट्रिगर पिकर खोजा जा सकता है</strong> &mdash; इसे फ़िल्टर करने के लिए टाइप करना शुरू करें (<code>resolved</code>, <code>contract</code>, <code>delete</code>&hellip;)। हर घटना एक <strong>अकेले साझा write path</strong> से सक्रिय होती है, इसलिए इसका व्यवहार एक जैसा रहता है चाहे बदलाव ब्राउज़र से आया हो, REST API से, या किसी और वर्कफ़्लो से &mdash; यह भटक नहीं सकता।',
        'failures_heading' => 'इंजन की विफलताएँ अलग-थलग रहती हैं',
        'failures_callout' => '<strong>कोई बगदार वर्कफ़्लो होस्ट मॉड्यूल के रिक्वेस्ट को नहीं बिगाड़ सकता।</strong> हर dispatch एक try/catch में लपेटा जाता है और हर क्रिया की विफलता को चेन को रोके बिना निष्पादन पंक्ति में लॉग किया जाता है। अगर कोई वर्कफ़्लो वह करना बंद कर दे जिसकी आप उम्मीद करते हैं, तो वर्कफ़्लो के <em>Recent runs</em> पैनल की जाँच करें &mdash; विफलताएँ वहाँ मूल त्रुटि के साथ दिखती हैं, न कि उस पेज पर 500 के रूप में जिसने उन्हें ट्रिगर किया।',
        'ahead_heading' => 'आगे अभी क्या बाकी है',
        'ahead_li1' => '<strong>Tier 3 क्रियाएँ</strong> &mdash; Microsoft Graph: <code>graph_add_to_group</code>, <code>graph_assign_license</code>, <code>graph_disable_user</code>। वे new-starter / leaver ऑटोमेशन जो पेड ITSM सुइट के मुक़ाबले इस मॉड्यूल के होने को सही ठहराते हैं। मौजूदा tenant OAuth ढाँचे का दोबारा उपयोग करता है।',
        'ahead_li4' => '<strong>Dry-run मोड</strong> &mdash; किसी वर्कफ़्लो को असली घटना पर चलाएँ लेकिन क्रियाओं को निष्पादित करने के बजाय <em>लॉग</em> करें। ताकि इसे लाइव करने से पहले आप देख सकें कि क्या होता।',
        'ahead_li5' => '<strong>शुरुआती रेसिपी</strong> &mdash; सामान्य पैटर्न के लिए कॉपी-योग्य टेम्पलेट: new-starter onboarding, P1 incident response, SLA-breach escalation, license-renewal reminder।',
        'ahead_li6' => '<strong>Watchtower integration</strong> &mdash; विफल रन attention कार्ड के रूप में सामने आते हैं।',
        'ahead_li7' => '<strong>Workflow versioning</strong> &mdash; draft / publish / rollback।',
        'ahead_li8' => '<strong>Streaming AI co-author</strong> &mdash; कैनवास बनते समय claude.ai-जैसा लाइव आउटपुट।',
    ],
];
